import{_ as t,o as e,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"الموقف الجوهري «الواقع أساس»","description":"","frontmatter":{},"headers":[],"relativePath":"ar/09-现实为基根本立场.md","filePath":"ar/09-现实为基根本立场.md","lastUpdated":null}'),h={name:"ar/09-现实为基根本立场.md"};function l(o,a,i,n,s,p){return e(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="الموقف-الجوهري-«الواقع-أساس»" tabindex="-1">الموقف الجوهري «الواقع أساس» <a class="header-anchor" href="#الموقف-الجوهري-«الواقع-أساس»" aria-label="Permalink to &quot;الموقف الجوهري «الواقع أساس»&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>09</td></tr><tr><td>الوحدة</td><td>المبادئ العامة والإعدادات الأساسية</td></tr><tr><td>الكلمات المفتاحية</td><td>الواقع أساس، الحقيقة الوحيدة، حدود الخيال، التطوير بالقوانين، التحقق العملي</td></tr></tbody></table><h2 id="أولاً-التعريف-الأساسي-لمبدأ-«الواقع-أساس»" tabindex="-1">أولاً: التعريف الأساسي لمبدأ «الواقع أساس» <a class="header-anchor" href="#أولاً-التعريف-الأساسي-لمبدأ-«الواقع-أساس»" aria-label="Permalink to &quot;أولاً: التعريف الأساسي لمبدأ «الواقع أساس»&quot;">​</a></h2><p>«الواقع أساس» هو الموقف المعرفي الجوهري والمبدأ المنهجي لحضارة التكافل المرساة، ويعني أن جميع البنيات النظرية والتصاميم المؤسسية والممارسات الزراعية والابتكارات التقنية للحضارة يجب أن تتخذ العالم الواقعي الأساس الحقيقي الوحيد والمعيار النهائي للتحقق. «الواقع» يشير إلى العالم المادي والطاقي الموضوعي الذي يمكن إدراكه وقياسه والتحقق منه — الساحة الفعلية التي تحيا فيها الكائنات وتتطور.</p><p>يحمل موقف «الواقع أساس» ثلاثة معانٍ: أولاً، العالم الواقعي هو العالم الحقيقي الوحيد، والعوالم الخيالية (بما فيها عوالم الروايات والأساطير والخيال) منتجات تجارب فكرية ولا تمتلك واقعية موضوعية؛ ثانياً، يمكن لإعدادات العوالم الخيالية أن تكون مصدر إلهام وأداة تجارب فكرية، لكن لا يمكن استخدامها مباشرة أساساً للواقع — بل يجب أن تمر عبر تحقق القوانين الواقعية وتحويلها؛ ثالثاً، ما لا يوجد بعد في الواقع يمكن استنباطه وخلقه استنباطاً معقولاً بناءً على قوانين موضوعية مثبتة، لكن يجب أن يخضع هذا الخلق لاختبار الممارسة.</p><h2 id="ثانياً-لماذا-يجب-التمسك-بمبدأ-«الواقع-أساس»" tabindex="-1">ثانياً: لماذا يجب التمسك بمبدأ «الواقع أساس» <a class="header-anchor" href="#ثانياً-لماذا-يجب-التمسك-بمبدأ-«الواقع-أساس»" aria-label="Permalink to &quot;ثانياً: لماذا يجب التمسك بمبدأ «الواقع أساس»&quot;">​</a></h2><h3 id="_2-1-منع-الخلط-بين-الخيال-والواقع" tabindex="-1">2.1 منع الخلط بين الخيال والواقع <a class="header-anchor" href="#_2-1-منع-الخلط-بين-الخيال-والواقع" aria-label="Permalink to &quot;2.1 منع الخلط بين الخيال والواقع&quot;">​</a></h3><p>في حضارات الزراعة، تمتلك إعدادات العوالم الخيالية غالباً جاذبية قوية. يستلهم كثير من المزارعين إلهام الزراعة من الروايات والأساطير والملاحم، وهذا أمر طبيعي بحد ذاته. لكن إذا اعتُبرت إعدادات العوالم الخيالية قوانين واقعية مباشرة، تنشأ مشكلات خطيرة: الزراعة وفق إعدادات خيالية قد تؤدي إلى الانحراف؛ ووضع المؤسسات وفق إعدادات خيالية قد ينفصل عن الواقع؛ واتخاذ الشخصيات الخيالية أصناماً حقيقية قد يؤدي إلى الضياع الروحي. الوظيفة الأولى لموقف «الواقع أساس» هي رسم خط واضح بين الخيال والواقع، ومنع خلطهما.</p><h3 id="_2-2-ضمان-سلامة-وفعالية-ممارسة-الزراعة" tabindex="-1">2.2 ضمان سلامة وفعالية ممارسة الزراعة <a class="header-anchor" href="#_2-2-ضمان-سلامة-وفعالية-ممارسة-الزراعة" aria-label="Permalink to &quot;2.2 ضمان سلامة وفعالية ممارسة الزراعة&quot;">​</a></h3><p>الزراعة ممارسة جدية تمس أصل الحياة وتشغيل الطاقة؛ وأي نظرية خاطئة قد تؤدي إلى عواقب وخيمة. أنظمة الزراعة في العوالم الخيالية كثيراً ما يصممها المؤلفون لخدمة الحبكة، وقد لا تطابق القوانين الحقيقية لتشغيل الطاقة وتطور الحياة. إذا نقل المزارعون الإعدادات الخيالية دون تمييز، ففي أحسن الأحوال تكون الزراعة بلا جدوى ويضيع الوقت، وفي أسوأ الأحوال تنشأ اضطرابات طاقية وانحرافات في الزراعة وحتى أخطار على الحياة. يطلب موقف «الواقع أساس» أن تمر جميع نظريات الزراعة بتحقق الواقع وتثبيته، ضامناً سلامة وفعالية ممارسة الزراعة.</p><h3 id="_2-3-الحفاظ-على-واقعية-المؤسسات-الحضارية" tabindex="-1">2.3 الحفاظ على واقعية المؤسسات الحضارية <a class="header-anchor" href="#_2-3-الحفاظ-على-واقعية-المؤسسات-الحضارية" aria-label="Permalink to &quot;2.3 الحفاظ على واقعية المؤسسات الحضارية&quot;">​</a></h3><p>يجب أن يستند تصميم المؤسسات الحضارية إلى عوامل موضوعية كالظروف الاجتماعية الواقعية وحالة الموارد والعلاقات بين الأعراق. فإذا صُممت المؤسسات منفصلة عن الواقع، معتمدة على خيال جميل أو إعدادات خيالية فقط، تتحول إلى قلاع في الهواء لا يمكن تنفيذها. يطلب موقف «الواقع أساس» أن تنطلق جميع التصاميم المؤسسية من الواقع، وتمر باختبار الممارسة، وتُضبط وتُحسن باستمرار وفق تغيرات الواقع.</p><h3 id="_2-4-توفير-منهجية-موثوقة-للابتكار-والخلق" tabindex="-1">2.4 توفير منهجية موثوقة للابتكار والخلق <a class="header-anchor" href="#_2-4-توفير-منهجية-موثوقة-للابتكار-والخلق" aria-label="Permalink to &quot;2.4 توفير منهجية موثوقة للابتكار والخلق&quot;">​</a></h3><p>لا يهدف «الواقع أساس» إلى تقييد الابتكار والخيال، بل إلى تزويدهما بمنهجية موثوقة. يمكن للخيال أن يكون مصدر إلهام وأداة تجارب فكرية، لكن الخلق الحقيقي يجب أن يستند إلى فهم عميق للقوانين الواقعية. ما لا يوجد في الواقع يمكن خلقه ما دام يطابق القوانين الموضوعية؛ لكن إذا خالف القوانين الموضوعية، فمهما كان الخيال جميلاً لا يمكن أن يصبح واقعاً. يجمع موقف «الواقع أساس» بين «الخيال الجريء» و«التحقق الحذر»، مؤصلاً الابتكار على أساس متين.</p><h2 id="ثالثاً-مبادئ-معالجة-العلاقة-بين-الخيال-والواقع" tabindex="-1">ثالثاً: مبادئ معالجة العلاقة بين الخيال والواقع <a class="header-anchor" href="#ثالثاً-مبادئ-معالجة-العلاقة-بين-الخيال-والواقع" aria-label="Permalink to &quot;ثالثاً: مبادئ معالجة العلاقة بين الخيال والواقع&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المبدأ</th><th>المعنى</th><th>المتطلبات المحددة</th></tr></thead><tbody><tr><td>مبدأ التمييز</td><td>التمييز الصارم بين الإعدادات الخيالية والقوانين الواقعية</td><td>يجب على أي نظرية أن تعلن بوضوح ما إذا كان مصدرها إلهاماً خيالياً أم تحققاً واقعياً</td></tr><tr><td>مبدأ الاستلهام</td><td>يمكن للخيال أن يكون مصدر إلهام وتجارب فكرية</td><td>تشجيع استلهام الخيال، مع وجوب تحويله عبر القوانين الواقعية</td></tr><tr><td>مبدأ التحقق</td><td>يجب أن تخضع جميع النظريات لتحقق الممارسة الواقعية</td><td>النظريات غير المتحقق منها فرضيات فقط، لا أساس لتوجيه الممارسة</td></tr><tr><td>مبدأ التحويل</td><td>يجب تحويل الإعدادات الخيالية إلى أشكال تطابق القوانين الواقعية</td><td>إعادة صياغة المفاهيم الخيالية بلغة علم الطاقة وعلم القوانين الواقعيين</td></tr><tr><td>مبدأ الحدود</td><td>حقوق وواجبات العوالم الخيالية لا تمتد إلى الواقع</td><td>عدم الاعتراف بفاعلية هويات وعقود وأسباب العوالم الخيالية في الواقع</td></tr></tbody></table><h2 id="رابعاً-«ما-نقصه-الخيال-يُكمَّل-بالواقع،-وما-لا-يوجد-في-الواقع-يُخلق-بالتطوير-القائم-على-القوانين»" tabindex="-1">رابعاً: «ما نقصه الخيال يُكمَّل بالواقع، وما لا يوجد في الواقع يُخلق بالتطوير القائم على القوانين» <a class="header-anchor" href="#رابعاً-«ما-نقصه-الخيال-يُكمَّل-بالواقع،-وما-لا-يوجد-في-الواقع-يُخلق-بالتطوير-القائم-على-القوانين»" aria-label="Permalink to &quot;رابعاً: «ما نقصه الخيال يُكمَّل بالواقع، وما لا يوجد في الواقع يُخلق بالتطوير القائم على القوانين»&quot;">​</a></h2><p>هذا هو المبدأ التشغيلي الأساسي لموقف «الواقع أساس»، ويتضمن جانبين:</p><h3 id="_4-1-ما-نقصه-الخيال-يُكمَّل-بالواقع" tabindex="-1">4.1 ما نقصه الخيال يُكمَّل بالواقع <a class="header-anchor" href="#_4-1-ما-نقصه-الخيال-يُكمَّل-بالواقع" aria-label="Permalink to &quot;4.1 ما نقصه الخيال يُكمَّل بالواقع&quot;">​</a></h3><p>عندما يكون الإلهام أو الإعدادات المستمدة من العوالم الخيالية ناقصة أو غير مترابطة أو غير مطابقة للقوانين الواقعية، يجب استكمالها وتصحيحها بالمعارف والقوانين المثبتة في الواقع. مثلاً، قد يصف نظام زراعة خيالي تقسيم المراتب فقط دون توضيح آلية تشغيل الطاقة؛ عندها تُستخدم نظرية تداول الطاقة الواقعية لاستكمال آلية تشغيله. وقد تنتهك تقنية خيالية قانون حفظ الطاقة الأساسي؛ عندها تُستخدم القوانين الواقعية لتصحيح إعداداتها.</p><p>عملية الاستكمال ليست لصقاً بسيطاً بين الخيال والواقع، بل إعادة تنظيم العناصر المعقولة من الخيال في منظومة نظرية مترابطة تطابق القوانين الواقعية، مع اتخاذ القوانين الواقعية إطاراً.</p><h3 id="_4-2-ما-لا-يوجد-في-الواقع-يُخلق-بالتطوير-القائم-على-القوانين" tabindex="-1">4.2 ما لا يوجد في الواقع يُخلق بالتطوير القائم على القوانين <a class="header-anchor" href="#_4-2-ما-لا-يوجد-في-الواقع-يُخلق-بالتطوير-القائم-على-القوانين" aria-label="Permalink to &quot;4.2 ما لا يوجد في الواقع يُخلق بالتطوير القائم على القوانين&quot;">​</a></h3><p>عندما لا يوجد شيء أو قدرة ما بعد في الواقع، لكن يمكن استنتاج إمكانية وجودها من قوانين موضوعية مثبتة، يجوز إجراء تطوير وخلق معقولين بناءً على القوانين. هذا الخلق ليس تخيلاً من العدم، بل امتداد منطقي وتحقيق تقني قائمان على قوانين موجودة.</p><p>مثلاً، التطبيق التقني لثمرة المضاعفة حالة نموذجية لـ«الخلق بالتطوير القائم على القوانين». نشأت ثمرة المضاعفة أصلاً من إعدادات أعمال خيالية، لكن باحثي الحضارة التكافلية أعادوا صياغة آلتها المركزية (المضاعفة والتضخيم) بلغة علم الطاقة وعلم القوانين الواقعيين، وطوّروا تقنية مضاعفة قابلة للتحقيق الهندسي استناداً إلى قوانين تضخيم الطاقة ورنين القوانين. هذه العملية استفادت من الإلهام الخيالي والتزمت بدقة بالقوانين الواقعية معاً.</p><p>يجب أن تخضع نتائج الخلق لاختبار الممارسة. فالخلق الذي لا يثبت في الواقع أنه فعال وآمن ومستقر لا يمكن إدراجه في النظام الرسمي للحضارة التكافلية.</p><h2 id="خامساً-تطبيقات-«الواقع-أساس»-في-المجالات-المختلفة" tabindex="-1">خامساً: تطبيقات «الواقع أساس» في المجالات المختلفة <a class="header-anchor" href="#خامساً-تطبيقات-«الواقع-أساس»-في-المجالات-المختلفة" aria-label="Permalink to &quot;خامساً: تطبيقات «الواقع أساس» في المجالات المختلفة&quot;">​</a></h2><h3 id="_5-1-في-مجال-الزراعة" tabindex="-1">5.1 في مجال الزراعة <a class="header-anchor" href="#_5-1-في-مجال-الزراعة" aria-label="Permalink to &quot;5.1 في مجال الزراعة&quot;">​</a></h3><p>يجب أن تمر جميع أنظمة الزراعة بمسار «التحقق الواقعي»: من البناء النظري إلى التجارب صغيرة النطاق، ثم إلى التعميم واسع النطاق؛ ولكل مرحلة بيانات أثر قابلة للقياس وإعادة الإنتاج. طرق الزراعة غير المتحقق منها واقعياً لا تكون إلا «طرقاً تجريبية»، مع وسم تحذيري بالمخاطر، ولا يجوز تعميمها كنظام رسمي.</p><h3 id="_5-2-في-المجال-التقني" tabindex="-1">5.2 في المجال التقني <a class="header-anchor" href="#_5-2-في-المجال-التقني" aria-label="Permalink to &quot;5.2 في المجال التقني&quot;">​</a></h3><p>يجب أن تتبع جميع تقنيات هندسة القوانين مسار التطوير «الجدوى النظرية — التحقق التجريبي — التحقيق الهندسي — تقييم السلامة». الأساس النظري للتقنيات يجب أن يكون قوانين موضوعية مثبتة؛ وللنتائج مؤشرات قابلة للقياس؛ وللسلامة تقييم صارم.</p><h3 id="_5-3-في-مجال-المؤسسات-الاجتماعية" tabindex="-1">5.3 في مجال المؤسسات الاجتماعية <a class="header-anchor" href="#_5-3-في-مجال-المؤسسات-الاجتماعية" aria-label="Permalink to &quot;5.3 في مجال المؤسسات الاجتماعية&quot;">​</a></h3><p>يجب أن يستند تصميم جميع المؤسسات الاجتماعية إلى مسوح اجتماعية واقعية وتحليل بيانات. الإصلاحات المؤسسية الكبرى يجب أن تبدأ بتجارب صغيرة النطاق، وتقييم الأثر، ثم التعميم التدريجي. معايير تقييم المؤسسات يجب أن تكون مؤشرات واقعية قابلة للقياس الكمي، لا أفكاراً مجردة أو إعدادات خيالية.</p><h3 id="_5-4-في-مجال-التاريخ-والأركيولوجيا" tabindex="-1">5.4 في مجال التاريخ والأركيولوجيا <a class="header-anchor" href="#_5-4-في-مجال-التاريخ-والأركيولوجيا" aria-label="Permalink to &quot;5.4 في مجال التاريخ والأركيولوجيا&quot;">​</a></h3><p>يجب أن يستند بحث الأحداث التاريخية والحضارات القديمة إلى أدلة مادية ومصادر تاريخية قابلة للتحقق. محتوى الأساطير والملاحم يمكن أن يكون موضوعاً للبحث الثقافي، لكن لا يمكن اعتباره حقائق تاريخية مباشرة. يتبع العمل الأثري بروتوكول التدني المنخفض المتمثل في «مرآة النسخ + الأركيولوجيا عن بعد في فضاء العزل، وإعادة نقل المعرفة فقط»، بما يضمن ألا تغير الأنشطة الأثرية الواقع التاريخي.</p><h2 id="سادساً-فهم-أعمق-لمفهوم-«الواقع»" tabindex="-1">سادساً: فهم أعمق لمفهوم «الواقع» <a class="header-anchor" href="#سادساً-فهم-أعمق-لمفهوم-«الواقع»" aria-label="Permalink to &quot;سادساً: فهم أعمق لمفهوم «الواقع»&quot;">​</a></h2><p>تجدر الإشارة خاصة إلى أن «الواقع» في موقف «الواقع أساس» ليس مفهوماً ساكناً مغلقاً، بل مفهوماً ديناميكياً يُعرف ويُتسع باستمرار.</p><p>أولاً، يتسع نطاق الواقع باستمرار مع تطور الحضارة. فالظواهر التي كانت تعد «خارقة للطبيعة» أُدرجت في نطاق الواقع مع الفهم الأعمق للطاقة والقوانين. آلية المرساة، والتنقل بين المستويات، والتفاعل في مجالات الوعي وغيرها قد تبدو «خيالية» للحضارات الدنيا، لكنها موجودة موضوعياً في واقع الحضارات العليا.</p><p>ثانياً، يتعمق فهم القوانين الواقعية باستمرار. النظريات التي تعد اليوم «قوانين» قد تُصحح أو تُستبدل غداً بنظريات أعمق. موقف «الواقع أساس» ليس تمسكاً بالفهم الموجود، بل التمسك بالطريقة الجوهرية المتمثلة في «جعل الممارسة المعيار الوحيد لاختبار الحقيقة»، مع تعميق فهم الواقع باستمرار.</p><p>أخيراً، يحوي الواقع إمكانات لا نهائية. بناءً على القوانين الموجودة، يمكننا استنباط إمكانات كثيرة لم تتحقق بعد، وتحويلها إلى واقع بوسائل تقنية. «الواقع أساس» ليس تقييداً للإمكانات، بل ضماناً بأن يبنى تحقيق الإمكانات على أساس موثوق.</p><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>«الواقع أساس» هو الموقف الجوهري لحضارة التكافل المرساة، ونقطة انطلاق وختام جميع نظرياتها وممارساتها. يطلب منا امتلاك خيال منفتح نستلهم منه من الخيال والملاحم، وواقعية صارمة نضع بها كل إلهام تحت اختبار القوانين الواقعية. ما نقصه الخيال يُكمَّل بالواقع، وما لا يوجد في الواقع يُخلق بالتطوير القائم على القوانين — هذا المبدأ يوحد عضوياً الخيال والواقع، والإلهام والقوانين، والخلق والتحقق، مؤمناً ضمانات منهجية موثوقة للتطور المستمر للحضارة التكافلية.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (هنغ يوانتشو: النظرة الشاملة للكون)</li><li>16-倍增果实技术化原理 (مبادئ تقنية ثمرة المضاعفة)</li><li>84-考古协议总纲 (الخطوط العامة لبروتوكول الأركيولوجيا)</li></ul>',43)])])}const b=t(h,[["render",l]]);export{_ as __pageData,b as default};
